# zbx for macOS on Apple Silicon: brew install zigbox/tap/zigbox
#
# Generated by `zig build mac-release` in Zigbox/zigbox. It installs the prebuilt binary, signed
# with Developer ID and notarized, from the GitHub release; it does not build from source.
class Zigbox < Formula
  desc "Rootless container runtime for Linux, and for macOS through a small virtual machine"
  homepage "https://github.com/Zigbox/zigbox"
  url "https://github.com/Zigbox/zigbox/releases/download/v0.1.0/zbx-0.1.0-macos-arm64.zip"
  version "0.1.0"
  sha256 "84fa826ea9359e95a18c397d39242d0d15280ee41405b9a03f209add0c77b0c6"
  # zbx is MIT; the binary carries a Linux kernel and VM tools under the GPL (sources on the
  # vm-kernel-6.18.59 and vm-deps-alpine-3.20 releases of Zigbox/zigbox).
  license all_of: ["MIT", "GPL-2.0-only"]

  depends_on arch: :arm64
  depends_on :macos

  def install
    bin.install "zbx"
  end

  test do
    # Neither command starts the virtual machine.
    assert_match "zbx #{version}", shell_output("#{bin}/zbx --version")
    assert_match "virtualization", shell_output("#{bin}/zbx explain E1001")
  end
end
